    // Build adjacency list
    List<Set<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new HashSet<>());
    }
    for (int[] path : paths) {
        if (path.length < 2) continue;
        int u = path[0];
        int v = path[1];
        // Ensure valid nodes
        if (u >= 0 && u < n && v >= 0 && v < n) {
            adj.get(u).add(v);
            // Since the problem says "paths between adjacent", assume undirected
            adj.get(v).add(u);
        }
    }

    int startNode = start[0];
    int endNode = end[0];

    // BFS to find if path exists
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();
    queue.add(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (node == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

