public double trimMean(int[] arr) {
    int n = arr.length;
    int removeCount = n / 20;

    Arrays.sort(arr);

    int start = removeCount;
    int end = n - removeCount;

    double sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    int count = end - start;
    return count > 0 ? sum / count : 0;
}

