public boolean canArrange(int[] arr, int k) {
        int n = arr.length;
        if (n % 2 != 0) {
            return false;
        }
        int[] freq = new int[k];
        for (int num : arr) {
            int mod = num % k;
            if (mod < 0) {
                mod += k;
            }
            freq[mod]++;
        }

        for (int i = 1; i <= k / 2; i++) {
            if (i == k - i) {
                if (freq[i] % 2 != 0) {
                    return false;
                }
            } else {
                if (freq[i] != freq[k - i]) {
                    return false;
                }
            }
        }

        if (k > 1) {
            if (freq[0] % 2 != 0) {
                return false;
            }
        }

        return true;
    }

