    int totalNeeded = 0;
    int leftParts = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftParts++;
        } else {
            if (leftParts > 0) {
                leftParts--;
            } else {
                totalNeeded++;
            }
        }
    }
    totalNeeded += leftParts;
    return totalNeeded;
}

