public int findMinFibonacciNumbers(int k) {
    // Step 1: Generate all Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int next = a + b;
        if (next > k) break;
        fibs.add(next);
        a = b;
        b = next;
    }

    // Step 2: Greedy approach - repeatedly subtract the largest Fibonacci number <= k
    int count = 0;
    int index = fibs.size() - 1;
    while (k > 0) {
        while (index >= 0 && fibs.get(index) > k) {
            index--;
        }
        if (index < 0) break;
        k -= fibs.get(index);
        count++;
    }

    return count;
}

