public String makeGood(String s) {
    char[] arr = new char[s.length()];
    int top = -1;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (top >= 0) {
            char prev = arr[top];
            if (Math.abs(prev - c) == 32) {
                top--;
                continue;
            }
        }
        top++;
        arr[top] = c;
    }

    return new String(arr, 0, top + 1);
}

