public String getSmallestString(int n, int k) {
    // Start with all 'a' characters
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Remaining value to distribute
    int remaining = k - n;

    // Distribute the remaining value from the end (to keep lexicographically smallest)
    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) break;

        // The maximum we can add to this position is 25 (from 'a' to 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }

    return new String(result);
}

