public static int singleNumber(int[] nums) {
    long ones = 0;
    long twos = 0;
    for (int n : nums) {
        long common = ones & n;
        ones += n & ~(ones & twos);
        twos += common & twos;
        // If a bit appears three times, it should be cleared from both ones and twos
        long threes = ones & twos;
        ones &= ~threes;
        twos &= ~threes;
    }
    return (int) ones;
}

