public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Integer> queue = new LinkedList<>();

    if (low == 0) {
        // Special case: 0 is a stepping number, but it has no digit to compare with
        // We handle it separately to avoid issues with the BFS starting from 1-9
    }

    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add(num);
        }

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int newNum = num * 10 + (lastDigit - 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
        if (lastDigit < 9) {
            int newNum = num * 10 + (lastDigit + 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
    }

    if (low == 0) {
        result.add(0);
        Collections.sort(result);
    }

    return result;
}

