public static int countDigitOne(int n) {
    if (n <= 0) return 0;

    int count = 0;
    long digit = 1;
    while (digit <= n) {
        long high = n / (digit * 10);
        long current = (n / digit) % 10;
        long low = n % digit;

        if (current < 1) {
            count += high * digit;
        } else if (current == 1) {
            count += high * digit + low + 1;
        } else {
            count += (high + 1) * digit;
        }

        digit *= 10;
    }

    return count;
}

