public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    // A number is a power of two if it has exactly one bit set in its binary representation.
    // For such numbers, n & (n - 1) will be 0.
    return (n & (n - 1)) == 0;
}

