public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absN = Math.abs(n);

    String numStr = String.valueOf(absN);
    StringBuilder result = new StringBuilder();

    int len = numStr.length();
    for (int i = 0; i < len; i++) {
        result.append(numStr.charAt(i));
        int remainingDigits = len - i - 1;
        if (remainingDigits > 0 && remainingDigits % 3 == 0) {
            result.append('.');
        }
    }

    String finalStr = result.toString();
    return negative ? "-" + finalStr : finalStr;
}

