public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquareSum = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            isSquareSum[i][j] = (sqrt * sqrt == sum);
        }
    }

    // Use backtracking with memoization
    // State: (position, used mask)
    // We'll use DFS with bitmask DP
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[n][1 << n];
    // Initialize dp with -1 to indicate uncomputed states
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (1 << n); j++) {
            dp[i][j] = -1;
        }
    }

    int result = 0;
    // Try each element as the first in the permutation
    for (int i = 0; i < n; i++) {
        result += dfs(1, 1 << i, i, A, isSquareSum, dp, n);
    }

    return result;
}

