public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    int numDiagonals = rows + cols - 1;
    int index = 0;

    for (int d = 0; d < numDiagonals; d++) {
        // Determine the starting point of the diagonal
        int row, col;
        if (d < cols) {
            row = 0;
            col = d;
        } else {
            row = d - (cols - 1);
            col = cols - 1;
        }

        // Traverse the diagonal
        int len = Math.min(d + 1, cols, rows, numDiagonals - d);
        if (d % 2 == 0) {
            // Even diagonal: traverse from top-right to bottom-left
            for (int i = 0; i < len; i++) {
                result[index++] = mat[row + i][col - i];
            }
        } else {
            // Odd diagonal: traverse from bottom-left to top-right
            int startRow = row + len - 1;
            int startCol = col - len + 1;
            for (int i = 0; i < len; i++) {
                result[index++] = mat[startRow - i][startCol + i];
            }
        }
    }

    return result;
}

