public static int calculateUniqueSum(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        // First pass: count occurrences of each number
        int maxVal = 0;
        for (int num : nums) {
            if (num > maxVal) {
                maxVal = num;
            }
        }

        // Handle negative numbers by tracking min
        int minVal = 0;
        for (int num : nums) {
            if (num < minVal) {
                minVal = num;
            }
        }

        // Use a HashMap approach for clarity and correctness
        java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }

        return sum;
    }

