public static int minPerfectSquareSum(int n) {
        if (n <= 0) {
            return 0;
        }

        // dp[i] represents the minimum number of perfect squares that sum to i
        int[] dp = new int[n + 1];

        // Initialize with large values
        for (int i = 1; i <= n; i++) {
            dp[i] = i; // worst case: sum of 1s
        }

        // Fill the dp table
        for (int i = 1; i <= n; i++) {
            // Try all perfect squares less than or equal to i
            int j = 1;
            while (j * j <= i) {
                int square = j * j;
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
                j++;
            }
        }

        return dp[n];
    }

